import{_ as t,a,b as r,c as i,d as o,e as l,f as n,g as d,h as u,i as c,j as p}from"./chunks/power.BtpUPTqz.js";import{_ as m,C as h,o as f,c as g,E as v,a2 as b}from"./chunks/framework.Dkj3JE0_.js";const D=JSON.parse('{"title":"Impact de l’ouragan Helene","description":"","frontmatter":{"pageClass":"project-case-study","title":"Impact de l’ouragan Helene","order":1},"headers":[],"relativePath":"fr/projects/NCCP.md","filePath":"fr/projects/NCCP.md"}'),q={name:"fr/projects/NCCP.md"};function x(_,e,P,C,y,k){const s=h("ProjectHero");return f(),g("div",null,[v(s,{index:"01",eyebrow:"Analyse urbaine · Reconstruction après catastrophe",title:"Évaluation de l’impact de l’ouragan Helene dans l’ouest de la Caroline du Nord",summary:"Une évaluation multi-sources qui relie les dégâts physiques de la tempête aux conditions économiques et sociales qui façonnent la reprise.",year:"2024",role:"Analyse de données et recherche",methods:"Analyse géospatiale · Données publiques · Indicateurs de résilience",image:"/images/NCCP/precipitation.png","image-alt":"Carte des précipitations de l’ouragan Helene et des comtés touchés",report:"/NCCP_slides.pdf"}),e[0]||(e[0]=b('<h2 id="la-question" tabindex="-1">La question <a class="header-anchor" href="#la-question" aria-label="Permalink to &quot;La question&quot;">​</a></h2><p>Ce projet évalue les effets de l’ouragan Helene sur l’ouest de la Caroline du Nord. L’évaluation comprend une analyse globale des impacts de la tempête, un classement des comtés touchés, la situation avant Helene, ainsi que les points clés pour la reprise et la résilience future.</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte&quot;">​</a></h2><p>L’analyse s’appuie sur des données de plusieurs sources de référence : NOAA, le National Weather Service (NWS), le bureau climatique de l’État de Caroline du Nord, Duke Energy, le service forestier et le département de l’Agriculture de Caroline du Nord. Nous avons validé les zones touchées et mené une étude rétrospective à partir des données du recensement et du département du Commerce de l’État.</p><h2 id="synthese-des-impacts" tabindex="-1">Synthèse des impacts <a class="header-anchor" href="#synthese-des-impacts" aria-label="Permalink to &quot;Synthèse des impacts&quot;">​</a></h2><ul><li><strong>Comtés les plus touchés :</strong> Buncombe, McDowell, Henderson, Rutherford, Transylvania, Polk, Yancey, Mitchell, Avery</li><li><strong>Types de dégâts :</strong><ul><li><strong>Réseau électrique :</strong> infrastructures gravement endommagées, avec des zones de réparation complexes identifiées.</li><li><strong>Forêts :</strong> six comtés sont les plus touchés, notamment McDowell (130 805 acres) et Buncombe (89 440 acres).</li><li><strong>Inondations et glissements de terrain :</strong> surtout dans les comtés de Yancey, Avery et McDowell.</li></ul></li></ul><h2 id="analyse-retrospective" tabindex="-1">Analyse rétrospective <a class="header-anchor" href="#analyse-retrospective" aria-label="Permalink to &quot;Analyse rétrospective&quot;">​</a></h2><p>Avant Helene, la résilience des comtés variait selon :</p><ul><li><strong>La démographie :</strong> certains comtés comptaient une forte proportion de locataires et une population vieillissante.</li><li><strong>Les revenus et la pauvreté :</strong> des taux de croissance des revenus et des baisses de la pauvreté contrastés.</li><li><strong>Le logement :</strong> plusieurs comtés connaissaient une faible hausse des prix immobiliers et un taux d’effort locatif élevé.</li><li><strong>Le tissu d’entreprises :</strong> une forte proportion de petites entreprises (moins de 500 000 $ de chiffre d’affaires annuel) dans des zones durement touchées comme Mitchell et Yancey signale une vulnérabilité.</li></ul><h2 id="impact-sur-les-entreprises" tabindex="-1">Impact sur les entreprises <a class="header-anchor" href="#impact-sur-les-entreprises" aria-label="Permalink to &quot;Impact sur les entreprises&quot;">​</a></h2><ul><li>Les entreprises ont été cartographiées selon leur taille et leur concentration géographique.</li><li>Les zones où la part de petites entreprises est élevée sont considérées comme moins résilientes.</li><li>Les dégâts d’infrastructure et les coupures de courant ont fortement touché les petites entreprises, surtout dans les zones rurales et montagneuses.</li></ul><h2 id="pistes-pour-la-suite" tabindex="-1">Pistes pour la suite <a class="header-anchor" href="#pistes-pour-la-suite" aria-label="Permalink to &quot;Pistes pour la suite&quot;">​</a></h2><ol><li><strong>Données à constituer :</strong> résilience des infrastructures, santé économique, taux de vacance et migrations après Helene.</li><li><strong>Recensement des programmes :</strong> cartographier les financements fédéraux, étatiques et locaux disponibles.</li><li><strong>Actions stratégiques :</strong><ul><li>Soutenir les populations vulnérables.</li><li>Redynamiser les entreprises locales.</li><li>Renforcer la résilience face aux catastrophes futures.</li><li>Mettre en place des mesures antifraude.</li></ul></li></ol><hr><h2 id="synthese-des-impacts-1" tabindex="-1">Synthèse des impacts <a class="header-anchor" href="#synthese-des-impacts-1" aria-label="Permalink to &quot;Synthèse des impacts&quot;">​</a></h2><div class="figure"><img src="'+t+'" alt="Carte des comtés les plus touchés"><p class="caption">Carte des comtés les plus touchés, avec les zones de réparation complexe et de reconstruction.</p></div><h2 id="analyse-retrospective-1" tabindex="-1">Analyse rétrospective <a class="header-anchor" href="#analyse-retrospective-1" aria-label="Permalink to &quot;Analyse rétrospective&quot;">​</a></h2><div class="figure"><img src="'+a+'" alt="Analyse des ratios de logement"><p class="caption">Ratios propriétaires/locataires, hausse des prix immobiliers et taux d’effort locatif par comté.</p></div><h2 id="impact-sur-les-entreprises-1" tabindex="-1">Impact sur les entreprises <a class="header-anchor" href="#impact-sur-les-entreprises-1" aria-label="Permalink to &quot;Impact sur les entreprises&quot;">​</a></h2><div class="figure"><img src="'+r+'" alt="Répartition des petites et grandes entreprises"><p class="caption">Répartition des petites et grandes entreprises et effet sur la résilience.</p></div><h2 id="pistes-pour-la-suite-1" tabindex="-1">Pistes pour la suite <a class="header-anchor" href="#pistes-pour-la-suite-1" aria-label="Permalink to &quot;Pistes pour la suite&quot;">​</a></h2><div class="figure"><img src="'+i+'" alt="Cadre pour la reprise"><p class="caption">Cadre résumant les points clés pour les politiques et les financements après Helene.</p></div><h2 id="vue-d-ensemble-des-degats-forestiers" tabindex="-1">Vue d’ensemble des dégâts forestiers <a class="header-anchor" href="#vue-d-ensemble-des-degats-forestiers" aria-label="Permalink to &quot;Vue d’ensemble des dégâts forestiers&quot;">​</a></h2><div class="figure"><img src="'+o+'" alt="Vue d’ensemble des dégâts forestiers"><p class="caption">Zones forestières endommagées dans les comtés touchés.</p></div><h2 id="detail-des-degats-forestiers" tabindex="-1">Détail des dégâts forestiers <a class="header-anchor" href="#detail-des-degats-forestiers" aria-label="Permalink to &quot;Détail des dégâts forestiers&quot;">​</a></h2><div class="figure"><img src="'+l+'" alt="Détail des dégâts forestiers"><p class="caption">Ventilation détaillée des dégâts forestiers dans l’ouest de la Caroline du Nord.</p></div><h2 id="hausse-des-prix-immobiliers" tabindex="-1">Hausse des prix immobiliers <a class="header-anchor" href="#hausse-des-prix-immobiliers" aria-label="Permalink to &quot;Hausse des prix immobiliers&quot;">​</a></h2><div class="figure"><img src="'+n+'" alt="Hausse des prix immobiliers"><p class="caption">Évolution des prix immobiliers par comté.</p></div><h2 id="ecart-entre-prix-immobiliers-et-revenus" tabindex="-1">Écart entre prix immobiliers et revenus <a class="header-anchor" href="#ecart-entre-prix-immobiliers-et-revenus" aria-label="Permalink to &quot;Écart entre prix immobiliers et revenus&quot;">​</a></h2><div class="figure"><img src="'+d+'" alt="Écart entre prix immobiliers et revenus"><p class="caption">Écart entre les prix immobiliers et le revenu médian.</p></div><h2 id="taux-d-effort-locatif" tabindex="-1">Taux d’effort locatif <a class="header-anchor" href="#taux-d-effort-locatif" aria-label="Permalink to &quot;Taux d’effort locatif&quot;">​</a></h2><div class="figure"><img src="'+u+'" alt="Graphique du taux d’effort locatif"><p class="caption">Part de la population supportant un taux d’effort locatif élevé.</p></div><h2 id="repartition-des-grandes-entreprises" tabindex="-1">Répartition des grandes entreprises <a class="header-anchor" href="#repartition-des-grandes-entreprises" aria-label="Permalink to &quot;Répartition des grandes entreprises&quot;">​</a></h2><div class="figure"><img src="'+c+'" alt="Répartition des grandes entreprises"><p class="caption">Répartition des grandes entreprises dans les comtés touchés.</p></div><h2 id="degats-sur-le-reseau-electrique" tabindex="-1">Dégâts sur le réseau électrique <a class="header-anchor" href="#degats-sur-le-reseau-electrique" aria-label="Permalink to &quot;Dégâts sur le réseau électrique&quot;">​</a></h2><div class="figure"><img src="'+p+'" alt="Dégâts sur le réseau électrique"><p class="caption">Carte des zones où le réseau électrique a été endommagé.</p></div><h2 id="les-diapositives-d-origine-en-anglais" tabindex="-1">Les diapositives d’origine (en anglais) <a class="header-anchor" href="#les-diapositives-d-origine-en-anglais" aria-label="Permalink to &quot;Les diapositives d’origine (en anglais)&quot;">​</a></h2><div class="pdf-embed"><iframe src="/NCCP_slides.pdf#zoom=fitW" type="application/pdf" width="80%" height="800" style="border:none;overflow:hidden;"></iframe><div class="pdf-embed-fallback"><p>Aperçu PDF indisponible dans cette vue. Téléchargez plutôt le fichier :</p><p><a href="/NCCP_slides.pdf" target="_blank" download>📥 Télécharger les diapositives</a></p></div></div><p><a href="/NCCP_slides.pdf" target="_blank" download="">📥 Télécharger le rapport</a></p>',39))])}const H=m(q,[["render",x]]);export{D as __pageData,H as default};
